1	// pattern: Imperative Shell
2	//
3	// Gathers: AuthenticatedUser (full access required), DB pool, JSON body {name, privileged?}
4	// Processes: scope gate → validate name → generate + argon2id-hash a secret → store keyed (did, name)
5	// Returns: JSON {name, password, createdAt, privileged} — the secret is surfaced once, never again
6	//
7	// Implements: POST /xrpc/com.atproto.server.createAppPassword
8	
9	use axum::{extract::State, response::Json};
10	use rand_core::{OsRng, RngCore};
11	use serde::{Deserialize, Serialize};
12	
13	use common::{ApiError, ErrorCode};
14	
15	use crate::app::AppState;
16	use crate::auth::extractors::AuthenticatedUser;
17	use crate::auth::jwt::AuthScope;
18	use crate::auth::password::hash_password;
19	use crate::db::app_passwords::{insert_app_password, InsertOutcome};
20	use crate::lexicon::LexiconInput;
21	
22	/// Maximum accepted app-password name length (characters). A generous bound that rejects
23	/// obviously abusive input without constraining normal use.
24	const MAX_NAME_LEN: usize = 255;
25	
26	/// Characters an app-password secret is drawn from — lowercase RFC 4648 base32 (unambiguous,
27	/// case-insensitive to type). The secret is surfaced once; its exact charset is not part of any
28	/// wire contract (createSession treats it as an opaque password).
29	const SECRET_CHARSET: &[u8] = b"REDACTED";
30	
31	#[derive(Deserialize)]
32	pub struct CreateAppPasswordRequest {
33	    name: String,
34	    #[serde(default)]
35	    privileged: bool,
36	}
37	
38	#[derive(Serialize)]
39	#[serde(rename_all = "camelCase")]
40	pub struct CreateAppPasswordResponse {
41	    name: String,
42	    /// The generated secret, formatted `xxxx-xxxx-xxxx-xxxx`. Returned once at creation and
43	    /// never retrievable again (only its hash is stored).
44	    password: String,
45	    created_at: String,
46	    privileged: bool,
47	}
48	
49	/// Generate an app-password secret: 16 random charset characters grouped as `xxxx-xxxx-xxxx-xxxx`
50	/// (the familiar atproto app-password shape).
51	fn generate_app_password() -> String {
52	    let mut bytes = [0u8; 16];
53	    OsRng.fill_bytes(&mut bytes);
54	    let chars: Vec<char> = bytes
55	        .iter()
56	        .map(|&b| SECRET_CHARSET[(b as usize) % SECRET_CHARSET.len()] as char)
57	        .collect();
58	    let group = |range: std::ops::Range<usize>| chars[range].iter().collect::<String>();
59	    format!(
60	        "{}-{}-{}-{}",
61	        group(0..4),
62	        group(4..8),
63	        group(8..12),
64	        group(12..16)
65	    )
66	}
67	
68	/// POST /xrpc/com.atproto.server.createAppPassword
69	///
70	/// Mints a named app password for the authenticated account and returns the generated secret
71	/// once. The secret can then be used as the `password` in `createSession` to open a
72	/// (limited-scope) app-password session. Requires a full access-scope token — an app password
73	/// cannot mint more app passwords.
74	pub async fn create_app_password(
75	    user: AuthenticatedUser,
76	    State(state): State<AppState>,
77	    LexiconInput(payload): LexiconInput<CreateAppPasswordRequest>,
78	) -> Result<Json<CreateAppPasswordResponse>, ApiError> {
79	    if user.scope != AuthScope::Access {
80	        return Err(ApiError::new(
81	            ErrorCode::InvalidToken,
82	            "full access token required",
83	        ));
84	    }
85	    // Agent-derived tokens map to AuthScope::Access but must never manage app passwords.
86	    user.require_not_agent()?;
87	
88	    let name = payload.name;
89	    if name.trim().is_empty() {
90	        return Err(ApiError::new(
91	            ErrorCode::InvalidRequest,
92	            "app password name must not be empty",
93	        ));
94	    }
95	    if name.chars().count() > MAX_NAME_LEN {
96	        return Err(ApiError::new(
97	            ErrorCode::InvalidRequest,
98	            "app password name is too long",
99	        ));
100	    }
101	
102	    let password = generate_app_password();
103	    let password_hash = hash_password(&password)?;
104	    let created_at = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, true);
105	
106	    match insert_app_password(
107	        &state.db,
108	        &user.did,
109	        &name,
110	        &password_hash,
111	        payload.privileged,
112	        &created_at,
113	    )
114	    .await?
115	    {
116	        InsertOutcome::Created => Ok(Json(CreateAppPasswordResponse {
117	            name,
118	            password,
119	            created_at,
120	            privileged: payload.privileged,
121	        })),
122	        InsertOutcome::DuplicateName => Err(ApiError::new(
123	            ErrorCode::Conflict,
124	            "an app password with this name already exists",
125	        )),
126	    }
127	}
