32	/// GET /xrpc/com.atproto.server.listAppPasswords
33	///
34	/// Lists the authenticated account's app passwords — names, creation times, and privilege
35	/// only. The secrets are never returned (only their hashes are stored). Requires a full
36	/// access-scope token.
37	pub async fn list_app_passwords_handler(
38	    user: AuthenticatedUser,
39	    State(state): State<AppState>,
40	) -> Result<Json<ListAppPasswordsResponse>, ApiError> {
41	    if user.scope != AuthScope::Access {
42	        return Err(ApiError::new(
43	            ErrorCode::InvalidToken,
44	            "full access token required",
45	        ));
46	    }
47	    // Agent-derived tokens map to AuthScope::Access but must never see app-password metadata.
48	    user.require_not_agent()?;
49	
50	    let passwords = list_app_passwords(&state.db, &user.did)
51	        .await?
52	        .into_iter()
53	        .map(|p| AppPasswordItem {
54	            name: p.name,
55	            created_at: p.created_at,
56	            privileged: p.privileged,
57	        })
58	        .collect();
59	
60	    Ok(Json(ListAppPasswordsResponse { passwords }))
61	}
