1	// Agent consent + audit commands — the wallet side of the auth.md claim ceremony and the
2	// "My agents" management surface. Five Tauri IPC commands against the configured PDS:
3	//
4	//   preview_agent_claim(user_code)  — what would approving this code grant? (shown pre-biometric)
5	//   confirm_agent_claim(user_code)  — the human gate: flip the agent identity `active → claimed`
6	//   list_agents()                   — agent identities bound to this account
7	//   revoke_agent(registration_id)   — turn an agent off (idempotent on the server)
8	//   get_agent_audit(registration_id, cursor) — page an agent's append-only audit trail
9	//
10	// All five authenticate with the wallet's full session token (Keychain `"session-token"`, the
11	// credential the create flow leaves behind) — the PDS accepts it via its owner guard. Network
12	// cores are `_impl` functions taking `&CustosClient` so tests drive them against httpmock,
13	// mirroring `claim.rs`.
14	
15	use serde::{Deserialize, Serialize};
16	use serde_json::Value;
17	
18	use crate::http::CustosClient;
19	use crate::keychain;
20	
21	// ── Frontend-facing types (camelCase, mirroring the PDS responses) ─────────────
22	
23	/// One agent identity bound to this account (`GET /v1/agents` entry).
24	#[derive(Debug, Clone, Serialize, Deserialize)]
25	#[serde(rename_all = "camelCase")]
26	pub struct AgentSummary {
27	    pub registration_id: String,
28	    pub registration_type: String,
29	    #[serde(default, skip_serializing_if = "Option::is_none")]
30	    pub issuer: Option<String>,
31	    #[serde(default, skip_serializing_if = "Option::is_none")]
32	    pub subject: Option<String>,
33	    pub scopes: Vec<String>,
34	    /// `active` (awaiting the claim ceremony), `claimed`, or `revoked`.
35	    pub status: String,
36	    pub created_at: String,
37	    pub updated_at: String,
38	    #[serde(default, skip_serializing_if = "Option::is_none")]
39	    pub last_used_at: Option<String>,
40	}
41	
42	#[derive(Debug, Deserialize)]
43	struct ListAgentsResponse {
44	    agents: Vec<AgentSummary>,
45	}
46	
47	/// One audit event (`GET /v1/agents/{id}/audit` entry).
48	#[derive(Debug, Clone, Serialize, Deserialize)]
49	#[serde(rename_all = "camelCase")]
50	pub struct AgentAuditEvent {
51	    pub id: String,
52	    pub event_type: String,
53	    #[serde(default, skip_serializing_if = "Option::is_none")]
54	    pub did: Option<String>,
55	    #[serde(default, skip_serializing_if = "Option::is_none")]
