69	/// What confirming a `user_code` would grant (`POST /v1/agents/claim-preview`).
70	#[derive(Debug, Clone, Serialize, Deserialize)]
71	#[serde(rename_all = "camelCase")]
72	pub struct AgentClaimPreview {
73	    pub registration_id: String,
74	    pub registration_type: String,
