83	/// Result of a confirmed claim (`POST /agent/identity/claim/confirm`).
84	///
85	/// The ceremony endpoint answers in auth.md snake_case (`registration_id`) while the frontend
86	/// receives camelCase like every other IPC type — the alias accepts the server shape.
87	#[derive(Debug, Clone, Serialize, Deserialize)]
88	#[serde(rename_all = "camelCase")]
89	pub struct AgentClaimConfirmation {
90	    #[serde(alias = "registration_id")]
91	    pub registration_id: String,
92	    pub status: String,
93	    pub did: String,
94	}
