96	// ── Error type ──────────────────────────────────────────────────────────────────
97	
98	/// Errors for the agent consent/management commands.
99	///
100	/// Serializes as `{ "code": "SCREAMING_SNAKE_CASE" }` matching the existing error pattern. The
101	/// ceremony errors are distinct because the approval screen renders each as its own explicit
102	/// state (denial and expiry are never silent, per the design plan).
103	#[derive(Debug, Serialize, thiserror::Error)]
104	#[serde(tag = "code", rename_all = "SCREAMING_SNAKE_CASE")]
105	pub enum AgentsError {
106	    /// No wallet session token in the Keychain — onboarding never completed on this device.
107	    #[error("not authenticated")]
108	    NotAuthenticated,
109	    /// The code is unknown (mistyped, or the ceremony was restarted).
110	    #[error("unknown code")]
111	    CodeNotFound,
112	    /// The code's window lapsed; the agent must restart the ceremony.
113	    #[error("code expired")]
114	    CodeExpired,
115	    /// The code was already used.
116	    #[error("code already used")]
117	    AlreadyClaimed,
118	    /// The claim (or agent) belongs to a different account, or the identity was revoked.
119	    #[error("access denied")]
120	    AccessDenied,
121	    /// Unknown registration id (or one not bound to this account).
122	    #[error("unknown agent registration")]
123	    AgentNotFound,
124	    /// Too many attempts in the window (the claim endpoints share a tight per-IP limiter);
125	    /// the caller should back off and retry.
126	    #[error("rate limited")]
127	    RateLimited,
128	    /// Transport-level failure reaching the PDS.
129	    #[error("network error: {message}")]
130	    NetworkError { message: String },
131	    /// The PDS answered with something this wallet does not understand.
132	    #[error("unexpected response: {message}")]
133	    Unknown { message: String },
134	}
135	
136	/// auth.md-style `{ error, error_description }` body the ceremony endpoints return.
137	#[derive(Debug, Deserialize)]
138	struct CeremonyErrorBody {
139	    error: String,
140	}
141	
142	/// Map a confirm/preview ceremony error code to the typed variant the frontend renders.
143	fn map_ceremony_error(error_code: &str) -> AgentsError {
144	    match error_code {
145	        "invalid_user_code" | "invalid_request" => AgentsError::CodeNotFound,
146	        "claim_expired" => AgentsError::CodeExpired,
147	        "claimed_or_in_flight" => AgentsError::AlreadyClaimed,
148	        "access_denied" => AgentsError::AccessDenied,
149	        other => AgentsError::Unknown {
150	            message: format!("ceremony error: {other}"),
151	        },
152	    }
153	}
154	
155	fn network_error(e: reqwest::Error) -> AgentsError {
156	    AgentsError::NetworkError {
157	        message: e.to_string(),
158	    }
159	}
160	
161	/// Read the wallet's full session token from the Keychain.
162	fn session_token() -> Result<String, AgentsError> {
163	    let bytes = keychain::get_item("session-token").map_err(|e| {
164	        tracing::warn!(error = %e, "no session-token in Keychain for agent command");
165	        AgentsError::NotAuthenticated
166	    })?;
167	    String::from_utf8(bytes).map_err(|_| AgentsError::NotAuthenticated)
168	}
