170	// ── Network cores (testable against httpmock) ──────────────────────────────────
171	
172	async fn list_agents_impl(
173	    client: &CustosClient,
174	    token: &str,
175	) -> Result<Vec<AgentSummary>, AgentsError> {
176	    let resp = client
177	        .get_with_bearer("/v1/agents", token)
178	        .await
179	        .map_err(network_error)?;
180	    match resp.status().as_u16() {
181	        200 => {
182	            let body: ListAgentsResponse = resp.json().await.map_err(|e| AgentsError::Unknown {
183	                message: format!("failed to parse /v1/agents response: {e}"),
184	            })?;
185	            Ok(body.agents)
186	        }
187	        401 | 403 => Err(AgentsError::NotAuthenticated),
188	        429 => Err(AgentsError::RateLimited),
189	        other => Err(AgentsError::Unknown {
190	            message: format!("GET /v1/agents returned {other}"),
191	        }),
192	    }
193	}
194	
195	async fn revoke_agent_impl(
196	    client: &CustosClient,
197	    token: &str,
198	    registration_id: &str,
199	) -> Result<(), AgentsError> {
200	    let resp = client
201	        .post_with_bearer(
202	            &format!("/v1/agents/{registration_id}/revoke"),
203	            &serde_json::json!({}),
204	            token,
205	        )
206	        .await
207	        .map_err(network_error)?;
208	    match resp.status().as_u16() {
209	        200 => Ok(()),
210	        401 | 403 => Err(AgentsError::NotAuthenticated),
211	        404 => Err(AgentsError::AgentNotFound),
212	        429 => Err(AgentsError::RateLimited),
213	        other => Err(AgentsError::Unknown {
214	            message: format!("revoke returned {other}"),
215	        }),
216	    }
217	}
218	
219	async fn get_agent_audit_impl(
220	    client: &CustosClient,
221	    token: &str,
222	    registration_id: &str,
223	    cursor: Option<&str>,
224	) -> Result<AgentAuditPage, AgentsError> {
225	    let path = match cursor {
226	        Some(c) => format!(
227	            "/v1/agents/{registration_id}/audit?cursor={}",
228	            urlencoding::encode(c)
229	        ),
230	        None => format!("/v1/agents/{registration_id}/audit"),
231	    };
232	    let resp = client
233	        .get_with_bearer(&path, token)
234	        .await
235	        .map_err(network_error)?;
236	    match resp.status().as_u16() {
237	        200 => resp.json().await.map_err(|e| AgentsError::Unknown {
238	            message: format!("failed to parse audit response: {e}"),
239	        }),
240	        401 | 403 => Err(AgentsError::NotAuthenticated),
241	        404 => Err(AgentsError::AgentNotFound),
242	        429 => Err(AgentsError::RateLimited),
243	        other => Err(AgentsError::Unknown {
244	            message: format!("audit returned {other}"),
245	        }),
246	    }
247	}
