249	async fn preview_agent_claim_impl(
250	    client: &CustosClient,
251	    token: &str,
252	    user_code: &str,
253	) -> Result<AgentClaimPreview, AgentsError> {
254	    let resp = client
255	        .post_with_bearer(
256	            "/v1/agents/claim-preview",
257	            &serde_json::json!({ "userCode": user_code }),
258	            token,
259	        )
260	        .await
261	        .map_err(network_error)?;
262	    match resp.status().as_u16() {
263	        200 => resp.json().await.map_err(|e| AgentsError::Unknown {
264	            message: format!("failed to parse claim preview: {e}"),
265	        }),
266	        401 | 403 => Err(AgentsError::NotAuthenticated),
267	        // The preview endpoint deliberately collapses every failure shape into one uniform 404.
268	        404 => Err(AgentsError::CodeNotFound),
269	        429 => Err(AgentsError::RateLimited),
270	        other => Err(AgentsError::Unknown {
271	            message: format!("claim preview returned {other}"),
272	        }),
273	    }
274	}
275	
276	async fn confirm_agent_claim_impl(
277	    client: &CustosClient,
278	    token: &str,
279	    user_code: &str,
280	) -> Result<AgentClaimConfirmation, AgentsError> {
281	    let resp = client
282	        .post_with_bearer(
283	            "/agent/identity/claim/confirm",
284	            &serde_json::json!({ "user_code": user_code }),
285	            token,
286	        )
287	        .await
288	        .map_err(network_error)?;
289	    let status = resp.status();
290	    if status.is_success() {
291	        return resp.json().await.map_err(|e| AgentsError::Unknown {
292	            message: format!("failed to parse confirm response: {e}"),
293	        });
294	    }
295	    if status.as_u16() == 401 {
296	        return Err(AgentsError::NotAuthenticated);
297	    }
298	    if status.as_u16() == 429 {
299	        return Err(AgentsError::RateLimited);
300	    }
301	    match resp.json::<CeremonyErrorBody>().await {
302	        Ok(body) => Err(map_ceremony_error(&body.error)),
303	        Err(_) => Err(AgentsError::Unknown {
304	            message: format!("confirm returned {status}"),
305	        }),
306	    }
307	}
