8	/**
9	 * Error returned by the sovereign change-handle flow.
10	 * Matches `HandleChangeError` in `handle_change.rs`
11	 * (`#[serde(tag = "code", rename_all = "SCREAMING_SNAKE_CASE", rename_all_fields = "camelCase")]`) —
12	 * codes must match exactly.
13	 *
14	 * `SESSION_LOCKED` is the cue to run the passwordless {@link sovereignLogin} (biometric) and retry:
15	 * the identity's full-access session could not be restored/refreshed without a fresh device-key proof.
16	 */
17	export type HandleChangeError =
18	  // The wallet holds no authorized rotation key for this DID, so it cannot self-sign.
19	  | { code: 'WALLET_NOT_AUTHORIZED' }
20	  // The identity is locked — run sovereignLogin(did) and retry. `reason` mirrors ensureIdentitySession.
21	  | { code: 'SESSION_LOCKED'; reason: UnlockReason }
22	  // The hosting PDS or plc.directory rate-limited the request; `retryAfter` is the server's Retry-After.
23	  | { code: 'RATE_LIMITED'; retryAfter: string | null }
24	  // The requested handle is already taken / reserved on the hosting PDS.
25	  | { code: 'HANDLE_NOT_AVAILABLE'; message: string }
26	  // The requested handle is syntactically invalid or not a served domain.
27	  | { code: 'INVALID_HANDLE'; message: string }
28	  // updateHandle failed for a reason the wallet doesn't model specially (e.g. 401/403/5xx).
29	  | { code: 'UPDATE_HANDLE_FAILED'; status: number; message: string }
30	  // The strict pre-sign guard rejected the op (something other than alsoKnownAs would change).
31	  | { code: 'GUARD_REJECTED'; reason: string }
32	  | { code: 'INVALID_AUDIT_LOG'; message: string }
33	  | { code: 'SIGNING_FAILED'; message: string }
34	  | { code: 'PLC_DIRECTORY_ERROR'; message: string }
35	  | { code: 'NETWORK_ERROR'; message: string }
36	  | { code: 'IDENTITY_NOT_FOUND'; message: string };
37	
38	/**
39	 * List the served handle domains the DID's HOSTING PDS offers
40	 * (`describeServer.availableUserDomains`, e.g. `[".ezpds-staging.up.railway.app"]`).
41	 *
42	 * Distinct from the create flow's `getAvailableUserDomains` (which targets the single configured
43	 * Custos): this discovers the identity's actual host, so a claimed/migrated DID gets the right list.
44	 */
45	export const getIdentityHandleDomains = (did: string): Promise<string[]> =>
46	  invoke('get_identity_handle_domains', { did });
47	
48	/**
49	 * Change a wallet-custodied did:plc identity's handle: `updateHandle` on the hosting PDS, then a
50	 * device-key-signed `alsoKnownAs` PLC op to plc.directory, then a cache refresh — passwordless
51	 * end to end.
52	 *
53	 * The biometric prompt precedes the IPC invocation (it gates the Secure-Enclave signing of the PLC
54	 * op); cancellation therefore reaches neither Rust signing code nor the network. If the identity's
55	 * session is locked, the call rejects with `SESSION_LOCKED` — run {@link sovereignLogin} and retry.
56	 *
57	 * `handle` is the full handle (e.g. `alice.ezpds-staging.up.railway.app`), NOT the bare label.
58	 * Resolves with the updated DID document.
59	 */
60	export const changeHandle = async (did: string, handle: string): Promise<ClaimResult> => {
61	  await authenticateBiometric('Confirm your handle change');
62	  return invoke('change_handle_cmd', { did, handle });
63	};
