1508	/// Request a PLC operation signature from the PDS.
1509	///
1510	/// Triggers email verification on the PDS. `requestPlcOperationSignature` is a
1511	/// no-input procedure: the request must carry NO body — a spec-strict PDS
1512	/// (bsky.social) rejects `{}` with `InvalidRequest: A request body was provided
1513	/// when none was expected` (our own route is laxer, which is how the `{}` shipped).
1514	pub async fn request_plc_operation_signature(
1515	    client: &crate::oauth_client::OAuthClient,
1516	) -> Result<(), PdsClientError> {
1517	    let resp = client
1518	        .post_no_body("/xrpc/com.atproto.identity.requestPlcOperationSignature")
1519	        .await
1520	        .map_err(|e| PdsClientError::NetworkError {
1521	            message: format!("request_plc_operation_signature failed: {}", e),
1522	        })?;
1523	
1524	    if resp.status().is_success() {
1525	        Ok(())
1526	    } else {
1527	        Err(classify_xrpc_response("requestPlcOperationSignature", resp).await)
1528	    }
1529	}
