9	  issuer?: string;
10	  subject?: string;
11	  scopes: string[];
12	  /** `active` = registered, awaiting the claim ceremony; then `claimed` or `revoked`. */
13	  status: 'active' | 'claimed' | 'revoked';
14	  createdAt: string;
15	  updatedAt: string;
16	  lastUsedAt?: string;
17	};
18	
19	/** One entry of an agent's append-only audit trail. */
20	export type AgentAuditEvent = {
21	  id: string;
22	  eventType:
23	    | 'registered'
24	    | 'claim_initiated'
25	    | 'claim_confirmed'
26	    | 'claim_expired'
27	    | 'token_exchanged'
28	    | 'repo_write'
29	    | 'blob_upload'
30	    | 'revoked';
31	  did?: string;
32	  detail?: Record<string, unknown>;
33	  createdAt: string;
34	};
35	
36	/** One page of audit events, newest first; `cursor` present means more pages exist. */
37	export type AgentAuditPage = {
38	  events: AgentAuditEvent[];
39	  cursor?: string;
40	};
41	
42	/** What confirming a claim-ceremony code would grant. */
43	export type AgentClaimPreview = {
44	  registrationId: string;
45	  registrationType: 'service_auth' | 'identity_assertion' | 'anonymous';
46	  issuer?: string;
47	  subject?: string;
48	  scopes: string[];
49	  userCodeExpiresAt: string;
50	};
51	
52	/** Result of a confirmed claim ceremony. */
53	export type AgentClaimConfirmation = {
54	  registrationId: string;
55	  status: string;
56	  did: string;
57	};
58	
59	/** Errors from the agent consent/management commands. */
60	export type AgentsError = {
61	  code:
62	    | 'NOT_AUTHENTICATED'
63	    | 'CODE_NOT_FOUND'
64	    | 'CODE_EXPIRED'
65	    | 'ALREADY_CLAIMED'
66	    | 'ACCESS_DENIED'
67	    | 'AGENT_NOT_FOUND'
68	    | 'RATE_LIMITED'
