486	    // ── agents ───────────────────────────────────────────────────────────────
487	    list_agents: (): AgentSummary[] => state.identities.flatMap((i) => i.agents.map((a) => a.summary)),
488	    revoke_agent: (args) => {
489	      const registrationId = String(args.registrationId ?? '');
