521	            issuer: 'did:web:agent.example',
522	            subject: identity.did,
523	            scopes: ['repo:write', 'blob:upload'],
524	            status: 'claimed',
525	            createdAt: now,
526	            updatedAt: now,
527	          },
528	          audit: [{ id: `${registrationId}-1`, eventType: 'claim_confirmed', did: identity.did, createdAt: now }],
529	        });
530	      }
531	      return { registrationId, status: 'claimed', did: identity?.did ?? '' };
532	    },
533	
534	    // ── biometric plugin (allow the gate) ────────────────────────────────────
535	    'plugin:biometric|authenticate': () => null,
536	    'plugin:biometric|status': () => ({
537	      isAvailable: true,
538	      biometryType: 1,
539	      error: null,
540	      errorCode: null,
541	    }),
542	  };
543	}
