545	function removeIdentity(state: WalletState, did: string): RemovalOutcome {
546	  const before = state.identities.length;
547	  state.identities = state.identities.filter((i) => i.did !== did);
548	  return {
549	    tombstoneCid: `bafyharnesstombstone${did.slice(-6)}`,
550	    wasLastIdentity: before > 0 && state.identities.length === 0,
551	  };
552	}
553	
554	/** An access/refresh expiry far enough out that the session never reads as expired. */
555	function farFuture(): number {
556	  return Date.parse('2030-01-01T00:00:00.000Z');
557	}
558	
559	function isoInHours(hours: number): string {
560	  const base = Date.parse('2026-07-15T12:00:00.000Z');
561	  return new Date(base + hours * 3600_000).toISOString();
562	}
