1	/**
2	 * Stateful in-memory fake for the identity-wallet harness (browser test mode).
3	 *
4	 * Pure TypeScript: no Tauri, no DOM, no network — so it is unit-testable in the
5	 * Node vitest environment (see `state.test.ts`). The registry (`registry.ts`) owns
6	 * the command→handler mapping and mutates a {@link WalletState} instance through the
7	 * helpers here; scenarios (`scenarios.ts`) seed fresh states from presets.
8	 *
9	 * The domain modeled mirrors what the wallet's screens actually read: managed
10	 * identities (each with a PLC-format DID document, a device key, PLC-monitor alerts,
11	 * and bound agents), plus the transient state the multi-step create / claim /
12	 * migration flows thread across commands.
13	 */
14	import type { UnauthorizedChange } from '$lib/ipc';
15	import type {
16	  AgentSummary,
17	  AgentAuditEvent,
18	} from '$lib/ipc';
19	
20	/** A `did:key` multibase string that is stable for a given seed (not a real key). */
21	export function fakeDeviceKeyId(seed: string): string {
22	  return `did:key:zHarnessDev${hashToken(seed)}`;
23	}
24	
25	/** A plausible-looking `did:plc` for a given seed. */
26	export function fakePlcDid(seed: string): string {
27	  return `did:plc:harness${hashToken(seed)}`;
28	}
29	
30	/** Deterministic base36-ish token from a string — keeps fakes readable and stable. */
31	function hashToken(seed: string): string {
32	  let h = 2166136261;
33	  for (let i = 0; i < seed.length; i++) {
34	    h = (h ^ seed.charCodeAt(i)) >>> 0;
35	    h = (h * 16777619) >>> 0;
36	  }
37	  return h.toString(36).padStart(7, '0').slice(0, 12);
38	}
39	
40	/** One agent bound to an identity, plus its append-only audit trail. */
41	export interface FakeAgent {
42	  summary: AgentSummary;
43	  audit: AgentAuditEvent[];
44	}
45	
46	/** One managed identity as the fake models it. */
47	export interface FakeIdentity {
48	  did: string;
49	  handle: string;
50	  pdsUrl: string;
51	  /** `did:key` of this identity's device key. */
52	  deviceKeyId: string;
53	  /** PLC rotation keys, `rotationKeys[0]` === deviceKeyId when the device is root. */
54	  rotationKeys: string[];
55	  /** PLC-monitor alerts surfaced on the home screen. */
56	  alerts: UnauthorizedChange[];
57	  /** Agents bound to this identity ("My agents"). */
58	  agents: FakeAgent[];
59	}
60	
61	/** Transient state for the multi-step import (claim) flow. */
62	export interface ClaimFlow {
63	  did: string;
64	  handle: string;
65	  pdsUrl: string;
66	  authenticated: boolean;
67	  verificationRequested: boolean;
68	}
69	
70	/** Transient state for the wallet-authorized outbound migration flow. */
71	export interface MigrationFlow {
72	  did: string;
73	  destPdsUrl: string;
74	  sourceAuthenticated: boolean;
75	  destinationCreated: boolean;
76	  repoTransferred: boolean;
77	  blobsTransferred: boolean;
78	  preferencesTransferred: boolean;
79	  verified: boolean;
80	  armed: boolean;
81	}
82	
83	/** Transient state for the create flow (account → DID ceremony → handle). */
84	export interface CreateFlow {
85	  claimCode?: string;
86	  email?: string;
87	  handle?: string;
88	  did?: string;
89	}
90	
91	/** The full wallet fake store. */
92	export interface WalletState {
93	  /** Configured PDS base URL, or null on first launch (drives the config screen). */
94	  pdsUrl: string | null;
95	  /** Available handle domains the configured PDS offers. */
96	  availableUserDomains: string[];
97	  appearance: 'system' | 'light' | 'dark' | null;
98	  biometricEnabled: boolean;
99	  identities: FakeIdentity[];
100	  create: CreateFlow | null;
101	  claim: ClaimFlow | null;
102	  migration: MigrationFlow | null;
103	}
104	
105	/** The default PDS the fake reports once configured. */
106	export const DEFAULT_PDS_URL = 'https://harness.pds.local';
107	
108	/** A fresh, empty wallet state (fresh-install baseline). */
109	export function emptyWalletState(): WalletState {
110	  return {
111	    pdsUrl: null,
112	    availableUserDomains: ['.harness.pds.local'],
113	    appearance: null,
114	    biometricEnabled: true,
115	    identities: [],
116	    create: null,
117	    claim: null,
118	    migration: null,
119	  };
120	}
121	
122	/** Build a PLC-format DID document for an identity (the shape the home screen reads). */
123	export function makeDidDoc(identity: FakeIdentity): Record<string, unknown> {
124	  return {
125	    did: identity.did,
126	    alsoKnownAs: [`at://${identity.handle}`],
127	    rotationKeys: identity.rotationKeys,
128	    verificationMethods: {
129	      atproto: identity.rotationKeys[0] ?? identity.deviceKeyId,
130	    },
131	    services: {
132	      atproto_pds: {
133	        type: 'AtprotoPersonalDataServer',
134	        endpoint: identity.pdsUrl,
135	      },
136	    },
137	  };
138	}
139	
140	/**
141	 * Seed a fresh identity. `deviceKeyIsRoot` controls whether the device key sits at
142	 * `rotationKeys[0]` — the "Root key" badge on the home card depends on this.
143	 */
144	export function seedIdentity(
145	  opts: {
146	    handle: string;
147	    pdsUrl?: string;
148	    did?: string;
149	    deviceKeyIsRoot?: boolean;
150	  }
151	): FakeIdentity {
152	  const pdsUrl = opts.pdsUrl ?? DEFAULT_PDS_URL;
153	  const did = opts.did ?? fakePlcDid(opts.handle);
154	  const deviceKeyId = fakeDeviceKeyId(did);
155	  const deviceKeyIsRoot = opts.deviceKeyIsRoot ?? true;
156	  const pdsKey = fakeDeviceKeyId(`${did}:pds`);
157	  const rotationKeys = deviceKeyIsRoot ? [deviceKeyId, pdsKey] : [pdsKey, deviceKeyId];
158	  return {
159	    did,
160	    handle: opts.handle,
161	    pdsUrl,
162	    deviceKeyId,
163	    rotationKeys,
164	    alerts: [],
165	    agents: [],
166	  };
167	}
168	
169	/** Build a fake unauthorized-change alert for the migration/recovery surfaces. */
170	export function seedAlert(seed: string, createdAt: string): UnauthorizedChange {
171	  return {
172	    cid: `bafyharness${hashToken(seed)}`,
173	    createdAt,
174	    signingKey: fakeDeviceKeyId(`${seed}:attacker`),
175	    operation: { type: 'plc_operation', note: 'harness-injected unauthorized change' },
176	  };
177	}
178	
179	/** Build a fake claimed agent with a minimal audit trail. */
180	export function seedAgent(seed: string, did: string): FakeAgent {
181	  const registrationId = `reg-${hashToken(seed)}`;
182	  const now = '2026-07-15T12:00:00.000Z';
183	  return {
184	    summary: {
185	      registrationId,
186	      registrationType: 'service_auth',
187	      issuer: `did:web:agent-${hashToken(seed)}.example`,
188	      subject: did,
189	      scopes: ['repo:write', 'blob:upload'],
190	      status: 'claimed',
191	      createdAt: now,
192	      updatedAt: now,
193	      lastUsedAt: now,
194	    },
195	    audit: [
196	      { id: `ev-${hashToken(seed)}-1`, eventType: 'registered', createdAt: now },
197	      { id: `ev-${hashToken(seed)}-2`, eventType: 'claim_confirmed', did, createdAt: now },
198	      { id: `ev-${hashToken(seed)}-3`, eventType: 'token_exchanged', createdAt: now },
199	    ],
200	  };
201	}
202	
203	/** Find a managed identity by DID, or undefined. */
204	export function findIdentity(state: WalletState, did: string): FakeIdentity | undefined {
205	  return state.identities.find((i) => i.did === did);
206	}
207	
208	/** Register (or replace) an identity in the store. Idempotent by DID. */
209	export function upsertIdentity(state: WalletState, identity: FakeIdentity): void {
210	  const idx = state.identities.findIndex((i) => i.did === identity.did);
211	  if (idx === -1) state.identities.push(identity);
212	  else state.identities[idx] = identity;
213	}
