1	/**
2	 * Named scenario presets for the identity-wallet fake harness.
3	 *
4	 * Each preset builds a fresh {@link WalletState} that puts the app in a known
5	 * starting condition, so an agent (or a human) can reproduce any UI state — including
6	 * rare ones — on demand via `window.__harness.scenario(name)`. Pure functions over
7	 * `state.ts`, unit-testable in the Node environment.
8	 */
9	import {
10	  DEFAULT_PDS_URL,
11	  emptyWalletState,
12	  seedAgent,
13	  seedAlert,
14	  seedIdentity,
15	  upsertIdentity,
16	  type WalletState,
17	} from './state';
18	
19	/** The canonical wallet scenario names. */
20	export type ScenarioName =
21	  | 'fresh-install'
22	  | 'one-identity'
23	  | 'multi-identity'
24	  | 'alert-active'
25	  | 'migration-in-flight'
26	  | 'agent-connected';
27	
28	/** The default scenario when `VITE_HARNESS` is set with no explicit choice. */
29	export const DEFAULT_SCENARIO: ScenarioName = 'one-identity';
30	
31	/** Every scenario builder, keyed by name. */
32	export const scenarios: Record<ScenarioName, () => WalletState> = {
33	  'fresh-install': () => emptyWalletState(),
34	
35	  'one-identity': () => {
36	    const state = emptyWalletState();
37	    state.pdsUrl = DEFAULT_PDS_URL;
38	    upsertIdentity(state, seedIdentity({ handle: 'alice.harness.pds.local' }));
39	    return state;
40	  },
41	
42	  'multi-identity': () => {
43	    const state = emptyWalletState();
44	    state.pdsUrl = DEFAULT_PDS_URL;
45	    upsertIdentity(state, seedIdentity({ handle: 'alice.harness.pds.local' }));
46	    upsertIdentity(
47	      state,
48	      seedIdentity({ handle: 'bob.harness.pds.local', deviceKeyIsRoot: false })
49	    );
50	    return state;
51	  },
52	
53	  'alert-active': () => {
54	    const state = emptyWalletState();
55	    state.pdsUrl = DEFAULT_PDS_URL;
56	    const identity = seedIdentity({ handle: 'alice.harness.pds.local' });
57	    // A recent unauthorized change so the recovery-window countdown is live.
58	    identity.alerts = [seedAlert(identity.did, isoHoursAgo(2))];
59	    upsertIdentity(state, identity);
60	    return state;
61	  },
62	
63	  'migration-in-flight': () => {
64	    const state = emptyWalletState();
65	    state.pdsUrl = DEFAULT_PDS_URL;
66	    const identity = seedIdentity({ handle: 'alice.harness.pds.local' });
67	    upsertIdentity(state, identity);
68	    // A prepared migration whose source is already authenticated and the destination
69	    // account created, so the migration screens land mid-flow.
70	    state.migration = {
71	      did: identity.did,
72	      destPdsUrl: 'https://destination.harness.pds.local',
73	      sourceAuthenticated: true,
74	      destinationCreated: true,
75	      repoTransferred: false,
76	      blobsTransferred: false,
77	      preferencesTransferred: false,
78	      verified: false,
79	      armed: false,
80	    };
81	    return state;
82	  },
83	
84	  'agent-connected': () => {
85	    const state = emptyWalletState();
86	    state.pdsUrl = DEFAULT_PDS_URL;
87	    const identity = seedIdentity({ handle: 'alice.harness.pds.local' });
88	    identity.agents = [seedAgent(identity.did, identity.did)];
89	    upsertIdentity(state, identity);
90	    return state;
91	  },
92	};
93	
94	/** Whether a string names a known scenario. */
95	export function isScenarioName(name: string): name is ScenarioName {
96	  return name in scenarios;
97	}
98	
99	/** Build a state for `name`, falling back to the default for an unknown name. */
100	export function buildScenario(name: string): WalletState {
101	  return isScenarioName(name) ? scenarios[name]() : scenarios[DEFAULT_SCENARIO]();
102	}
103	
104	function isoHoursAgo(hours: number): string {
105	  // Fixed reference clock keeps scenarios deterministic in tests; the exact instant
106	  // is irrelevant — only the relative age matters to the recovery-window UI.
107	  const base = Date.parse('2026-07-15T12:00:00.000Z');
108	  return new Date(base - hours * 3600_000).toISOString();
109	}
