12	 * is most commonly a whole number of seconds; it can also be an HTTP date, which we don't try to
13	 * parse precisely (we fall back to a generic "try again later"). The point is to tell the user this
14	 * is a rate limit — a wait — not a connectivity failure.
15	 */
16	export function formatRateLimitMessage(retryAfter: string | null): string {
17	  const lead = 'Your PDS is rate limiting requests.';
18	  if (retryAfter == null || retryAfter.trim() === '') {
19	    return `${lead} Please wait a moment and try again.`;
20	  }
21	  const seconds = Number(retryAfter.trim());
22	  if (Number.isInteger(seconds) && seconds > 0) {
23	    if (seconds < 60) {
24	      return `${lead} Try again in about ${seconds} second${seconds === 1 ? '' : 's'}.`;
25	    }
26	    const minutes = Math.ceil(seconds / 60);
27	    return `${lead} Try again in about ${minutes} minute${minutes === 1 ? '' : 's'}.`;
28	  }
29	  // Non-numeric Retry-After (e.g. an HTTP date) — don't over-parse; keep it honest.
30	  return `${lead} Please try again later.`;
31	}
32	
33	/**
34	 * Text for a `SERVER_ERROR` — the PDS's own error message, shown verbatim behind a short lead so a
35	 * third-party PDS's real reason reaches the user. Falls back when the server sent no message.
36	 */
37	export function formatServerErrorMessage(message: string): string {
38	  const trimmed = message.trim();
39	  return trimmed.length > 0 ? `Your PDS reported: ${trimmed}` : 'Your PDS rejected the request.';
40	}
